-- Généré par scripts/generate-exercise-library.ts — ne pas modifier à la main.
insert into public.exercises (slug, name, description, primary_muscle, secondary_muscles, equipment, difficulty, measurement, is_unilateral, instructions, safety_tips, caution_tags, default_rest_s)
values
  ('pompes', 'Pompes', 'Mouvement de poussée au poids du corps qui développe les pectoraux, les triceps et la stabilité du tronc. Réalisable avec des poignées pour soulager les poignets et augmenter l’amplitude.', 'chest', array['triceps', 'shoulders', 'core']::text[], '{}'::text[], 2, 'reps', false, array['Mains (ou poignées) un peu plus larges que les épaules, bras tendus.', 'Corps gainé de la tête aux talons : serrer les fessiers et le ventre.', 'Descendre en contrôlant, coudes à environ 45° du buste.', 'Marquer une courte pause en bas sans relâcher le gainage.', 'Pousser le sol pour remonter en gardant le corps aligné.']::text[], array['Ne pas laisser le bassin s’affaisser ni monter.', 'Arrêter en cas de douleur aux poignets, aux épaules ou à l’abdomen.', 'Si la tension abdominale est inconfortable, passer aux pompes inclinées.']::text[], array['abdominal', 'wrists']::text[], 75),
  ('pompes-inclinees', 'Pompes inclinées', 'Variante plus accessible des pompes, mains en appui sur un support surélevé (canapé, table basse, marche).', 'chest', array['triceps', 'shoulders']::text[], '{}'::text[], 1, 'reps', false, array['Mains sur un support stable, à hauteur de hanches ou un peu plus bas.', 'Reculer les pieds pour aligner tête, bassin et talons.', 'Descendre la poitrine vers le bord du support, coudes à 45°.', 'Pousser pour revenir bras tendus.']::text[], array['Vérifier que le support ne glisse pas.', 'Plus le support est bas, plus l’exercice est difficile.']::text[], '{}'::text[], 60),
  ('pompes-genoux', 'Pompes sur les genoux', 'Variante de pompes en appui sur les genoux, utile pour accumuler du volume avec une bonne technique.', 'chest', array['triceps', 'shoulders']::text[], '{}'::text[], 1, 'reps', false, array['Genoux au sol sur un tapis, mains sous les épaules.', 'Aligner genoux, bassin et épaules.', 'Descendre la poitrine en contrôlant puis pousser.']::text[], array['Protéger les genoux avec un tapis ou une serviette pliée.']::text[], '{}'::text[], 60),
  ('rowing-halteres', 'Rowing avec haltères', 'Tirage buste penché qui renforce le haut du dos et les biceps, et équilibre le travail de poussée.', 'back', array['biceps', 'shoulders']::text[], array['dumbbell']::text[], 2, 'reps', false, array['Pieds largeur de hanches, genoux légèrement fléchis.', 'Pencher le buste vers l’avant en gardant le dos droit (charnière de hanches).', 'Tirer les haltères vers le bas des côtes, coudes près du corps.', 'Serrer les omoplates en haut, puis redescendre lentement.']::text[], array['Garder le dos neutre, ne pas arrondir le bas du dos.', 'Choisir une charge qui permet de contrôler la descente.']::text[], array['lower_back']::text[], 90),
  ('rowing-unilateral', 'Rowing unilatéral', 'Tirage d’un bras en appui, qui permet de se concentrer sur chaque côté du dos.', 'back', array['biceps', 'shoulders', 'core']::text[], array['dumbbell']::text[], 2, 'reps', true, array['Position fente avant, main libre posée sur la cuisse avant.', 'Dos droit, buste incliné, haltère bras tendu sous l’épaule.', 'Tirer le coude vers la hanche, sans tourner le buste.', 'Redescendre lentement puis changer de côté après la série.']::text[], array['Garder les épaules parallèles au sol.', 'Ne pas tirer avec le bas du dos.']::text[], '{}'::text[], 75),
  ('developpe-sol', 'Développé au sol', 'Développé couché réalisé au sol avec haltères : l’amplitude limitée protège les épaules.', 'chest', array['triceps', 'shoulders']::text[], array['dumbbell']::text[], 1, 'reps', false, array['Allongé sur le dos, genoux fléchis, pieds à plat.', 'Haltères au-dessus de la poitrine, bras tendus.', 'Descendre jusqu’à ce que les coudes touchent légèrement le sol, à 45° du buste.', 'Pousser les haltères vers le plafond.']::text[], array['Ne pas faire rebondir les coudes au sol.', 'Garder les poignets alignés avec les avant-bras.']::text[], '{}'::text[], 90),
  ('tirage-elastique', 'Tirage avec élastique', 'Tirage horizontal assis avec bande élastique, idéal pour renforcer le dos sans charge lourde.', 'back', array['biceps', 'shoulders']::text[], array['resistance_band']::text[], 1, 'reps', false, array['Assis au sol, jambes tendues, élastique passé sous les pieds.', 'Buste droit, bras tendus devant soi.', 'Tirer les mains vers le nombril en serrant les omoplates.', 'Revenir lentement en contrôlant la tension.']::text[], array['Vérifier l’état de l’élastique avant usage.', 'Ne pas basculer le buste en arrière pour tirer.']::text[], '{}'::text[], 60),
  ('curl-biceps', 'Curl biceps', 'Flexion des coudes avec haltères pour renforcer les biceps.', 'biceps', array['forearms']::text[], array['dumbbell']::text[], 1, 'reps', false, array['Debout, haltères en main, paumes vers l’avant.', 'Coudes collés au buste, fléchir pour monter les haltères.', 'Marquer un temps en haut puis redescendre lentement.']::text[], array['Ne pas balancer le buste.', 'Descendre jusqu’à l’extension complète sans verrouiller brutalement.']::text[], '{}'::text[], 60),
  ('extension-triceps', 'Extension triceps', 'Extension des coudes avec un haltère tenu au-dessus de la tête.', 'triceps', array['shoulders']::text[], array['dumbbell']::text[], 1, 'reps', false, array['Debout ou assis, haltère tenu à deux mains au-dessus de la tête.', 'Garder les coudes pointés vers l’avant et proches de la tête.', 'Descendre l’haltère derrière la tête en fléchissant les coudes.', 'Tendre les bras pour remonter.']::text[], array['Contrôler la descente pour ne pas heurter la nuque.', 'Gainer le ventre pour ne pas cambrer.']::text[], array['shoulders']::text[], 60),
  ('squat-goblet', 'Squat goblet', 'Squat avec un haltère tenu contre la poitrine : renforce les cuisses et les fessiers en favorisant un buste droit.', 'quads', array['glutes', 'core']::text[], array['dumbbell']::text[], 2, 'reps', false, array['Pieds un peu plus larges que les hanches, pointes légèrement ouvertes.', 'Haltère tenu verticalement contre la poitrine.', 'Descendre en poussant les hanches en arrière et les genoux vers l’extérieur.', 'Remonter en poussant dans tout le pied.']::text[], array['Garder les talons au sol.', 'Descendre seulement aussi bas que le dos reste neutre.']::text[], array['knees']::text[], 90),
  ('squat-pause', 'Squat avec pause', 'Squat au poids du corps (ou avec haltère) avec une pause de 2 secondes en bas, pour renforcer le contrôle et la position basse.', 'quads', array['glutes', 'core']::text[], '{}'::text[], 2, 'reps', false, array['Pieds largeur d’épaules, bras tendus devant pour l’équilibre.', 'Descendre en contrôlant jusqu’à la position basse confortable.', 'Tenir 2 secondes sans relâcher la tension.', 'Remonter de façon dynamique.']::text[], array['Respirer pendant la pause, ne pas bloquer longtemps la respiration.']::text[], array['knees']::text[], 90),
  ('squat-poids-corps', 'Squat au poids du corps', 'Squat sans charge, pour apprendre le mouvement ou travailler en volume.', 'quads', array['glutes']::text[], '{}'::text[], 1, 'reps', false, array['Pieds largeur d’épaules.', 'Descendre hanches en arrière, buste fier.', 'Remonter en poussant dans les talons.']::text[], array['Genoux dans l’axe des pieds.']::text[], '{}'::text[], 60),
  ('fentes-arriere', 'Fentes arrière', 'Fente en reculant une jambe : travail unilatéral des cuisses et des fessiers, plus doux pour les genoux que la fente avant.', 'quads', array['glutes', 'hamstrings']::text[], '{}'::text[], 2, 'reps', true, array['Debout, pieds largeur de hanches (haltères en main en option).', 'Reculer une jambe et descendre jusqu’à frôler le sol avec le genou arrière.', 'Le genou avant reste au-dessus du pied.', 'Pousser sur la jambe avant pour revenir debout.']::text[], array['Garder le buste droit.', 'Faire des pas assez grands pour que le genou avant ne dépasse pas trop les orteils.']::text[], array['knees']::text[], 75),
  ('souleve-terre-roumain', 'Soulevé de terre roumain', 'Charnière de hanches avec haltères qui cible l’arrière des cuisses et les fessiers.', 'hamstrings', array['glutes', 'back']::text[], array['dumbbell']::text[], 2, 'reps', false, array['Debout, haltères devant les cuisses, genoux légèrement fléchis.', 'Pousser les hanches en arrière en gardant le dos droit.', 'Descendre les haltères le long des jambes jusqu’à mi-tibia ou à l’étirement.', 'Revenir en serrant les fessiers.']::text[], array['Ne jamais arrondir le dos.', 'Les haltères restent proches des jambes.', 'Stopper si une douleur lombaire apparaît.']::text[], array['lower_back']::text[], 90),
  ('developpe-epaules', 'Développé épaules', 'Poussée verticale avec haltères pour renforcer les épaules et les triceps.', 'shoulders', array['triceps', 'core']::text[], array['dumbbell']::text[], 2, 'reps', false, array['Debout ou assis, haltères à hauteur d’épaules, paumes vers l’avant.', 'Gainer le ventre et serrer les fessiers.', 'Pousser les haltères au-dessus de la tête sans cambrer.', 'Redescendre lentement à hauteur d’épaules.']::text[], array['Ne pas cambrer le bas du dos.', 'Réduire la charge si l’épaule pince.']::text[], array['shoulders']::text[], 90),
  ('elevations-laterales', 'Élévations latérales', 'Élévation des bras sur les côtés pour cibler la partie moyenne des épaules.', 'shoulders', '{}'::text[], array['dumbbell']::text[], 1, 'reps', false, array['Debout, haltères légers le long du corps, coudes très légèrement fléchis.', 'Monter les bras sur les côtés jusqu’à hauteur d’épaules.', 'Redescendre lentement.']::text[], array['Utiliser une charge légère.', 'Ne pas hausser les épaules.']::text[], array['shoulders']::text[], 60),
  ('dead-bug', 'Dead bug', 'Exercice de gainage allongé sur le dos qui apprend à stabiliser le bassin pendant que les membres bougent.', 'core', '{}'::text[], '{}'::text[], 1, 'reps', false, array['Allongé sur le dos, bras tendus vers le plafond, hanches et genoux à 90°.', 'Plaquer le bas du dos au sol et expirer.', 'Allonger lentement un bras derrière la tête et la jambe opposée.', 'Revenir puis alterner. Une répétition = un côté.']::text[], array['Le bas du dos ne doit pas se décoller du sol.', 'Réduire l’amplitude ou arrêter en cas de douleur abdominale.']::text[], array['abdominal']::text[], 60),
  ('bird-dog', 'Bird dog', 'Gainage à quatre pattes en allongeant bras et jambe opposés : doux pour le dos et l’abdomen.', 'core', array['glutes', 'back']::text[], '{}'::text[], 1, 'reps', false, array['À quatre pattes, mains sous les épaules, genoux sous les hanches.', 'Allonger un bras devant et la jambe opposée derrière.', 'Garder le bassin stable et le dos plat, puis revenir et alterner.']::text[], array['Ne pas cambrer en montant la jambe.']::text[], '{}'::text[], 45),
  ('pont-fessier', 'Pont fessier', 'Élévation du bassin allongé sur le dos pour renforcer les fessiers et l’arrière des cuisses.', 'glutes', array['hamstrings', 'core']::text[], '{}'::text[], 1, 'reps', false, array['Allongé sur le dos, genoux fléchis, pieds à plat proches des fesses.', 'Pousser dans les talons pour monter le bassin.', 'Serrer les fessiers en haut, sans cambrer.', 'Redescendre lentement.']::text[], array['L’effort doit se sentir dans les fessiers, pas dans le bas du dos.']::text[], '{}'::text[], 60),
  ('face-pull-elastique', 'Face pull à l’élastique', 'Tirage de l’élastique vers le visage, coudes hauts : renforce l’arrière des épaules et améliore la posture.', 'shoulders', array['back']::text[], array['resistance_band']::text[], 1, 'reps', false, array['Élastique fixé à hauteur de visage (porte, poteau).', 'Bras tendus devant, paumes vers le bas.', 'Tirer les mains vers le front en écartant les coudes vers l’extérieur et vers le haut.', 'Serrer les omoplates puis revenir lentement.']::text[], array['Vérifier la solidité du point d’ancrage.', 'Garder le cou détendu.']::text[], '{}'::text[], 60),
  ('planche-laterale', 'Planche latérale', 'Gainage sur le côté en appui sur l’avant-bras, qui renforce les obliques et la stabilité du bassin.', 'core', array['shoulders', 'glutes']::text[], '{}'::text[], 2, 'duration', false, array['Allongé sur le côté, coude sous l’épaule, jambes tendues.', 'Monter le bassin pour aligner chevilles, hanches et épaules.', 'Tenir la position en respirant calmement, puis changer de côté.', 'Variante facile : genoux fléchis au sol.']::text[], array['Ne pas laisser le bassin s’affaisser.', 'Arrêter en cas de douleur abdominale ou à l’épaule.']::text[], array['abdominal', 'shoulders']::text[], 45)
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, difficulty = excluded.difficulty,
  measurement = excluded.measurement, is_unilateral = excluded.is_unilateral, instructions = excluded.instructions,
  safety_tips = excluded.safety_tips, caution_tags = excluded.caution_tags, default_rest_s = excluded.default_rest_s;

delete from public.exercise_media where kind = 'animation';
insert into public.exercise_media (exercise_id, kind, data, alt, position)
select e.id, 'animation', m.data, m.alt, 0
